// Writes assets/build-stats.js: the real numbers the DATA MOMENT counters count up to.
//   scenes: scene modules in timeline/timing.js
//   frames: frames in the final render (duration x fps); verified against the MP4 by selfcheck
//   lines:  non-blank lines of code written for this film (index.html, scenes/, timeline/, tools/)
// Vendored libraries, fonts and this generated file are not counted.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const { SCENES, FPS, DURATION } = await import(pathToFileURL(path.join(root, "timeline/timing.js")).href);

const files = ["index.html"];
for (const dir of ["scenes", "timeline", "tools"]) {
  for (const f of fs.readdirSync(path.join(root, dir)).sort()) {
    if (/\.(js|mjs|py|sh)$/.test(f)) files.push(path.join(dir, f));
  }
}
let lines = 0;
const perFile = {};
for (const f of files) {
  const n = fs.readFileSync(path.join(root, f), "utf8").split("\n").filter((l) => l.trim()).length;
  perFile[f] = n;
  lines += n;
}
const stats = { scenes: SCENES.length, frames: Math.round(DURATION * FPS), lines, files: perFile };
fs.writeFileSync(
  path.join(root, "assets/build-stats.js"),
  `// Generated by tools/stats.mjs. Do not edit.\nwindow.MWC_STATS = ${JSON.stringify(stats, null, 2)};\n`,
);
console.log(`scenes ${stats.scenes}, frames ${stats.frames}, lines of code ${lines} (${files.length} files)`);
